export const meta = {
  description: 'Cold probe: two agents in two stages over a seeded notes.txt',
  params: {
    agents: {
      reader: { model: { type: 'string', default: 'default' }, effort: { type: 'enum', enum: ['low', 'medium', 'high'], default: 'low' }, timeoutMs: { type: 'number', default: 300000 } },
      writer: { model: { type: 'string', default: 'default' }, effort: { type: 'enum', enum: ['low', 'medium', 'high'], default: 'low' }, timeoutMs: { type: 'number', default: 300000 } },
    },
  },
};

phase('stage-one');
const first = await agent('reader', { prompt: 'Use the Read tool to read the file notes.txt in your workspace, then reply with the file\'s exact contents and nothing else.', allowedTools: ['Read'] });

phase('stage-two');
const second = await agent('writer', { prompt: 'Reply with the single word: DONE', allowedTools: [] });

return { stageOne: first, stageTwo: second };

